import hashlib,json,math,platform,re,time
from pathlib import Path
import torch
from dongxi_llms.instruction_data_lab import encode_messages
from dongxi_llms.student_prefix_lab import teacher_distribution,A,B,C
started=time.monotonic();torch.set_num_threads(1);D=torch.float64
def close(a,b):torch.testing.assert_close(torch.as_tensor(a,dtype=D),torch.as_tensor(b,dtype=D),atol=1e-12,rtol=1e-10)
out={}
conversation=encode_messages([{'role':'system','content':'short answer'},{'role':'user','content':'copy red'},{'role':'assistant','content':'red'}])
assert list(conversation.ids)==[1,2,16,17,5,3,10,6,5,4,6,5]
assert [i for i,x in enumerate(conversation.supervised) if x]==[10,11]
out['ownership']={'ids':conversation.ids,'supervised_target_positions':[10,11],'producing_positions':[9,10]}
p=torch.tensor([[.6,.3,.1],[.2,.3,.5],[1/3]*3],dtype=D)
z=p.log().requires_grad_();loss=(-z.log_softmax(-1)[0,0]-z.log_softmax(-1)[1,2])/2
gradient,=torch.autograd.grad(loss,z);close(gradient,[[-.2,.15,.05],[.1,.15,-.25],[0,0,0]])
zz=p.log().requires_grad_();broken=-zz.log_softmax(-1)[0,0];g2,=torch.autograd.grad(broken,zz);close(g2,[[-.4,.3,.1],[0,0,0],[0,0,0]])
out['sft']={'complete_mean_nll':float(loss.detach()),'gradient':gradient.tolist(),'without_END_nll':float(broken.detach()),'without_END_gradient':g2.tolist()}
aa=torch.tensor([[.2,-.4,.8],[.3,.5,-.1]],dtype=D,requires_grad=True)
bb=torch.tensor([[.6,-.2],[-.1,.7]],dtype=D,requires_grad=True)
gw=torch.tensor([[.1,-.3,.4],[.5,.2,-.6]],dtype=D)
factor=4/2;objective=(factor*(bb@aa)*gw).sum();ga,gb=torch.autograd.grad(objective,(aa,bb));close(ga,factor*bb.T@gw);close(gb,factor*gw@aa.T)
for zeros in ['B','both']:
 a=(aa.detach() if zeros=='B' else torch.zeros_like(aa)).requires_grad_();b=torch.zeros_like(bb).requires_grad_();oa=(factor*(b@a)*gw).sum();g_a,g_b=torch.autograd.grad(oa,(a,b));assert torch.equal(g_a,torch.zeros_like(g_a));assert (not torch.equal(g_b,torch.zeros_like(g_b))) if zeros=='B' else torch.equal(g_b,torch.zeros_like(g_b))
out['lora']={'A_gradient':ga.tolist(),'B_gradient':gb.tolist(),'rank8_1024_parameter_counts':[2*8*1024,1024**2],'zero_B_only_A_gradient_zero':True,'both_zero_both_gradients_zero':True}
sigmoid=lambda x:1/(1+math.exp(-x));prob=sigmoid(1)
report=json.loads(Path('experiments/reports/2026-10-04-preference-policy-cpu.json').read_text());scorers={}
for name in ['confounded','balanced']:
 weights=report['reward'][name]['weights'];margin=sum(x*y for x,y in zip(weights,[-1,3,3]));scorers[name]={'weights':weights,'margin':margin,'adversarial_probability':sigmoid(margin)}
close([scorers['confounded']['adversarial_probability'],scorers['balanced']['adversarial_probability']],[.9625042577209881,.13694736872407448])
out['BT']={'probability':prob,'hard_loss':-math.log(prob),'hard_score_gradients':[prob-1,1-prob],'soft_score_gradients':[prob-.7,.7-prob],'soft_optimal_margin':math.log(.7/.3),'retained_scorers':scorers}
q=[.6,.3,.1];r=[0,.5,1];opt={}
for beta in [.5,1]:
 weights=[a*math.exp(b/beta) for a,b in zip(q,r)];norm=sum(weights);pi=[w/norm for w in weights];stationarity=[reward-beta*(math.log(p/ref)+1) for p,ref,reward in zip(pi,q,r)];close(stationarity,[stationarity[0]]*3);opt[str(beta)]={'weights':weights,'Z':norm,'policy':pi,'stationarity_without_multiplier':stationarity}
margin=.5*math.log((.1/.01)/(.2/.1));out['DPO']={'optima':opt,'three_answer_margin':margin,'three_answer_loss':math.log1p(math.exp(-margin)),'initial_loss':math.log(2),'initial_and_changed_odds':[2,10]}
temps={};teacher=torch.tensor([2,.5,-1],dtype=D)
for tau in [1,2,4]:
 q=torch.softmax(teacher/tau,-1);student=torch.zeros(3,dtype=D,requires_grad=True);logp=torch.log_softmax(student/tau,-1);loss=tau**2*(q*(q.log()-logp)).sum();grad,=torch.autograd.grad(loss,student);close(grad,tau*(torch.full_like(q,1/3)-q));temps[str(tau)]={'teacher_probabilities':q.tolist(),'scaled_gradient':grad.tolist(),'unscaled_gradient':(grad/tau**2).tolist()}
ordinary=teacher_distribution([A,B],[C]);hinted=teacher_distribution([A,B],[C],hint=[B,A]);assert ordinary.argmax().item()==C and hinted.argmax().item()==A;close(ordinary[C],.8);close(hinted[A],.8)
out['distillation']={'temperatures':temps,'hard_gradient':[-2/3,1/3,1/3],'wrong_prefix':{'symbol_ids':[A,B],'past':[C],'ordinary_target':ordinary.argmax().item(),'hinted_target':hinted.argmax().item(),'target_probability':.8,'other_probability':.2/7}}
chapter=Path('book/chapters/09-supervised-fine-tuning.md').read_text();snippets=re.findall(r'```text\n(.*?)\n```',chapter,re.S)[:3];records=[]
for folder,snippet,reason,count in zip(['base','full400','lora400-fp32'],snippets,['max_tokens','turn_stop','max_tokens'],[64,5,64]):
 path=Path(f'experiments/reports/native-assistant-publication-20261005-{folder}-run-01/generation/responses.jsonl');row=json.loads(path.read_text().splitlines()[0]);assert row['item_id']=='test-100-copy' and row['response_text']==snippet and row['stop_reason']==reason and row['generated_tokens']==count
 records.append({'path':str(path),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'selected_item':row['item_id'],'response_sha256':row['response_text_sha256'],'stop_reason':reason,'generated_tokens':count})
out['actual_responses']=records
out['execution']={'status':'passed','python':platform.python_version(),'torch':torch.__version__,'elapsed_seconds':time.monotonic()-started,'boundary':'Bounded arithmetic/autograd/source replay; no decoder training or new model run.'}
print(json.dumps(out,indent=2))
